INSERT INTO news (date, lang, title, text) VALUES
 ('2026-11-14', 'es', 'Nueva entrada al modo en línea', 'Al entrar al juego en línea viajas por un túnel de datos con su propio sonido y el logo LAIKA 64 ONLINE sale de él hasta quedar al frente. La música se pausa y vuelve al terminar. A, B o START la saltan. El logo también es ahora el título de Jugar en línea.'),
 ('2026-11-14', 'en', 'A new way into online play', 'Entering online play takes you down a tunnel of data with its own sound, and the LAIKA 64 ONLINE logo comes out of it to the front. The music pauses and comes back after it. A, B or START skip it. The logo is also the title of Play online now.'),
 ('2026-11-14', 'pt', 'Nova entrada no modo online', 'Ao entrar no jogo online você atravessa um túnel de dados com som próprio e o logo LAIKA 64 ONLINE sai dele até ficar na frente. A música pausa e volta no final. A, B ou START pulam. O logo agora também é o título do Jogar online.'),
 ('2026-11-14', 'fr', 'Une nouvelle entrée en ligne', 'En entrant dans le jeu en ligne, tu traverses un tunnel de données avec son propre son et le logo LAIKA 64 ONLINE en sort jusqu''au premier plan. La musique se met en pause et reprend après. A, B ou START la passent. Le logo est aussi le titre de Jouer en ligne.'),
 ('2026-11-14', 'it', 'Nuovo ingresso nel gioco online', 'Entrando nel gioco online attraversi un tunnel di dati con il suo suono e il logo LAIKA 64 ONLINE ne esce fino a fermarsi davanti. La musica va in pausa e riprende alla fine. A, B o START la saltano. Il logo ora è anche il titolo di Gioca online.'),
 ('2026-11-14', 'de', 'Neuer Einstieg ins Online-Spiel', 'Beim Öffnen des Online-Spiels fliegst du durch einen Datentunnel mit eigenem Sound, und das LAIKA 64 ONLINE-Logo kommt nach vorne heraus. Die Musik pausiert und läuft danach weiter. A, B oder START überspringen es. Das Logo ist jetzt auch der Titel von Online spielen.'),
 ('2026-11-14', 'ru', 'Новый вход в игру по сети', 'При входе в игру по сети ты летишь по туннелю данных со своим звуком, а логотип LAIKA 64 ONLINE вылетает из него вперёд. Музыка встаёт на паузу и продолжается после. A, B или START пропускают заставку. Логотип теперь и заголовок экрана Игра по сети.');
